// PASO 1: Obtener datos del webhook y de la base de datos
const webhookData = $input.first().json;
const agentDataFromDB = $input.all()[1]?.json; // Datos del nodo PostgreSQL

// PASO 2: Verificar que tenemos datos del agente
if (!agentDataFromDB || !agentDataFromDB[0]) {
  throw new Error('No se encontró información del agente en la base de datos');
}

const agentRecord = agentDataFromDB[0];
console.log('✅ Agente obtenido de BD:', agentRecord.name);

// PASO 3: Extraer datos del mensaje de Telegram
const message = webhookData.body.message;
if (!message) {
  throw new Error('No se encontró mensaje en el webhook data');
}

const chatId = message.chat.id;
const messageText = message.text || '';
const userId = message.from.id;
const firstName = message.from.first_name || '';
const username = message.from.username || '';

// PASO 4: Obtener configuración del agente desde la BD
const botToken = agentRecord.bot_token;
const systemPrompt = agentRecord.prompt || 'Eres un asistente virtual amigable y útil.';

// PASO 5: Parsear configuración adicional desde platform_config
let businessContext = '';
let targetAudience = '';
let welcomeMessage = '';

if (agentRecord.platform_config) {
  try {
    const platformConfig = JSON.parse(agentRecord.platform_config);

    if (platformConfig.businessInfo) {
      businessContext = `\n\nInformación del negocio: ${platformConfig.businessInfo}`;
    }

    if (platformConfig.targetAudience) {
      targetAudience = `\nAudiencia objetivo: ${platformConfig.targetAudience}`;
    }

    if (platformConfig.prompts?.welcome) {
      welcomeMessage = platformConfig.prompts.welcome;
    }

    console.log('🎯 Configuración adicional cargada desde platform_config');
  } catch (error) {
    console.warn('⚠️ Error parsing platform_config:', error);
  }
}

// PASO 6: Construir el prompt final
const finalSystemPrompt = systemPrompt + businessContext + targetAudience;

// PASO 7: Verificar que tenemos el token del bot
if (!botToken) {
  throw new Error('No se encontró bot_token para el agente: ' + agentRecord.name);
}

console.log('🤖 Procesando mensaje para agente:', agentRecord.name);
console.log('📱 Chat ID:', chatId);
console.log('💬 Mensaje:', messageText);

return [{
  json: {
    // Datos del mensaje
    chatId: chatId,
    messageText: messageText,
    userId: userId,
    firstName: firstName,
    username: username,

    // Datos del agente desde BD
    botToken: botToken,
    agentId: agentRecord.id,
    agentName: agentRecord.name,
    botName: agentRecord.bot_name,

    // Contexto para IA
    messages: [
      {
        role: 'system',
        content: finalSystemPrompt
      },
      {
        role: 'user', 
        content: messageText
      }
    ],

    // Información adicional
    agentConfig: {
      welcomeMessage: welcomeMessage,
      businessContext: businessContext,
      targetAudience: targetAudience
    }
  }
}];
